# Initially generated by GitHub Copilot.

import os
import tempfile
import unittest

from tmpl_survey import survey_dot


class TestTmplSurveyEdgeMode(unittest.TestCase):
    def test_write_edge_template_dot_file_labels_templates_on_edges(self):
        stack_counts = {
            ("מ:פסוק", "C/מ:כפול"): 3,
            ("מ:אות-ג", "C/מ:כפול/מ:פסוק"): 2,
            ("מ:אות-ג", "C/מ:פסוק"): 5,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(stack_counts, dot_path)
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"C" -> "C::stack-end" [label="מ:פסוק (3)"]', dot_text)
        self.assertIn('"C" -> "C::stack::מ:פסוק" [label="מ:פסוק (7)"]', dot_text)
        self.assertIn(
            '"C::stack::מ:פסוק" -> "C::stack-end" [label="מ:אות-ג (7)"]',
            dot_text,
        )
        self.assertIn('"C::stack-end" [label="C end", tooltip="Stack end for C"]', dot_text)
        self.assertNotIn('"מ:פסוק";', dot_text)

    def test_write_edge_template_dot_file_applies_discard_set(self):
        stack_counts = {
            ("נוסח", "D"): 4,
            ("מ:פסוק", "D/נוסח"): 5,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(stack_counts, dot_path)
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"D" -> "D::stack-end" [label="מ:פסוק (5)"]', dot_text)
        self.assertNotIn('label="נוסח (', dot_text)
        self.assertIn("מ:כפול, נוסח have been discarded", dot_text)

    def test_write_edge_template_dot_file_includes_provenance(self):
        stack_counts = {
            ("מ:פסוק", "E"): 1,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(
                stack_counts,
                dot_path,
                generator_file=__file__,
            )
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn("generated by", dot_text)
        self.assertIn("graph [comment=", dot_text)


if __name__ == "__main__":
    unittest.main()
